import 'package:flutter/material.dart';
class PicturePuzzleGame extends StatefulWidget{const PicturePuzzleGame({super.key});@override State<PicturePuzzleGame> createState()=>_PicturePuzzleGameState();}
class _PicturePuzzleGameState extends State<PicturePuzzleGame>{final tiles=[1,2,3,4,5,6,7,8,0];int moves=0;void tap(int i){final z=tiles.indexOf(0),r=i~/3,c=i%3,zr=z~/3,zc=z%3;if((r-zr).abs()+(c-zc).abs()!=1)return;setState((){tiles[z]=tiles[i];tiles[i]=0;moves++;});}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Picture Puzzle')),body:Padding(padding:const EdgeInsets.all(24),child:Column(children:[Text('الحركات: $moves'),Expanded(child:GridView.builder(itemCount:9,gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:3),itemBuilder:(_,i)=>GestureDetector(onTap:()=>tap(i),child:Container(margin:const EdgeInsets.all(3),color:tiles[i]==0?Theme.of(c).colorScheme.surfaceContainerHighest:Theme.of(c).colorScheme.primary,child:Center(child:Text(tiles[i]==0?'':'${tiles[i]}',style:const TextStyle(fontSize:28,fontWeight:FontWeight.w900,color:Colors.white)))))))])));}